<script module lang="ts">
/**
 * Toast.Card: one toast in the viewport, with its timer, its dismissal and its exit.
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/toast.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { onDestroy } from 'svelte'

import {
  Icon,
  Render,
  TOAST_TONE_ICON,
  composingKey,
  focusAfterToast,
  joinSlot,
  removeToast,
  toast,
  toastClock,
  toastTimeLeft,
  watchEffect,
  type ToastRecord,
} from '@polymorph/svelte'
import { usePresence } from '@polymorph/svelte/motion'
import styles from '@polymorph/recipes/overlays/toast.module.css'
import Button from '../controls/Button.svelte'

export interface ToastCardProps {
  record: ToastRecord
  /**
   * The close button’s accessible name.
   */
  dismissLabel: string
  /**
   * The reader is on the list, so the timer waits.
   */
  paused: boolean
}
</script>

<script lang="ts">
let { record, dismissLabel, paused }: ToastCardProps = $props()
const joined = joinSlot(undefined, () => ({}))
let swipe = $state('')
let tracking = $state(false)
let startX = $state(0)
let deltaX = $state(0)
let card = $state<HTMLElement | null>(null)
const icon = $derived(record.tone === 'neutral' ? null : TOAST_TONE_ICON[record.tone])
const clock = $derived(toastClock())
const dismissible = $derived(record.dismissible !== false)
const dismiss = $derived((): void => {
  if (dismissible) toast.dismiss(record.id)
})
const act = $derived((): void => {
  record.action?.onClick()
  toast.dismiss(record.id)
})
const press = $derived((event: PointerEvent): void => {
  if (!dismissible || event.button !== 0 || (event.target as Element).closest('button') !== null)
    return
  tracking = true
  startX = event.clientX
  deltaX = 0
})
const drag = $derived((event: PointerEvent): void => {
  if (!tracking) return
  deltaX = Math.max(0, event.clientX - startX)
  if (deltaX > 0) swipe = 'move'
})
const lift = $derived((): void => {
  if (!tracking) return
  tracking = false
  if (swipe !== 'move') return
  if (deltaX > 50) {
    swipe = 'end'
    dismiss()
  } else {
    swipe = 'cancel'
    deltaX = 0
  }
})
const present = usePresence(
  () => record.closing !== true,
  () => card,
  'toast.enter',
)
const effect1 = () => {
  record.closing === true && focusAfterToast(card)
}
watchEffect(effect1, { watch: () => record.closing, mount: false })
const effect2 = () => {
  present.current || removeToast(record.id, record.raised)
}
watchEffect(effect2, { watch: () => present.current, mount: false })
let release3: (() => void) | undefined
const effect3 = () => {
  release3?.()
  const timer = setTimeout(
    () => {
      !paused &&
        record.closing !== true &&
        dismissible &&
        Number.isFinite(record.durationMs) &&
        toast.dismiss(record.id)
    },
    Number.isFinite(record.durationMs)
      ? toastTimeLeft(clock, record.revision, record.durationMs, !paused && record.closing !== true)
      : 0,
  )
  release3 = () => clearTimeout(timer)
}
watchEffect(effect3, { watch: () => [record.revision, paused, record.closing] })
onDestroy(() => release3?.())
</script>

{@render joined.start?.()
}{#if joined.shown
  }<li
    bind:this={card}
    class={styles.toast}
    style:--radix-toast-swipe-move-x={`${deltaX}px`}
    style:--radix-toast-swipe-end-x={`${deltaX}px`}
    tabindex="0"
    data-tone={record.tone}
    data-state={record.closing === true ? 'closed' : 'open'}
    data-swipe={swipe === '' ? undefined : swipe}
    data-swipe-direction="right"
    data-member="toast"
    onkeydown={(event) => { if (event.key === 'Escape' && !event.defaultPrevented && !composingKey(event)) (event.preventDefault(), dismiss()) }}
    onpointerdown={(event) => { press(event) }}
    onpointermove={(event) => { drag(event) }}
    onpointerup={() => { lift() }}
    onpointercancel={() => { lift() }}
    >{#if record.loading === true
      }<span class={[styles.tone, styles.wait]} aria-hidden="true"><Icon name="loading" /></span
    >{:else if icon !== null
      }<span class={styles.tone}><Icon name={icon} /></span
    >{/if
    }<div class={styles.text}
      ><div class={styles.title} data-toast-title="">{record.title}</div
      >{#if record.description !== undefined
        }<div class={styles.description}>{record.description}</div
      >{/if
      }{#if record.content !== undefined
        }<div class={styles.content} data-toast-content=""><Render node={record.content} /></div
      >{/if
    }</div
    >{#if record.action !== undefined
      }<div class={styles.action}
        ><Button
          variant="ghost"
          tone={record.tone === 'danger' ? 'danger' : 'accent'}
          size="sm"
          label={record.action?.label ?? ''}
          onClick={() => { act() }}
      /></div
    >{/if
    }{#if dismissible
      }<div class={styles.close}
        ><Button
          variant="ghost"
          tone="neutral"
          size="sm"
          iconOnly={true}
          icon="close"
          label={dismissLabel}
          onClick={() => { dismiss() }}
      /></div
    >{/if
  }</li
>{/if
}{@render joined.end?.()}
